    def test_secp192k1_sha256(
        self, name: str, pk: bytes, msg: bytes, sig: bytes, expected: bool
    ):
        decoder = SEC1Encoder()
        public_key = decoder.decode_public_key(pk, secp192k1)

        try:
            signature = DEREncoder.decode_signature(sig)
            result = verify(signature, msg, public_key, secp192k1, sha256)
            self.assertEqual(result, expected, name)
        except Exception:
            self.assertFalse(expected, name)
